head.b:skin:
:root {
  color-scheme: light;
  --bg: #f5f6f3;
  --surface: rgba(255, 255, 255, 0.75);
  --text: #1c1f1d;
  --muted: #6b716d;
  --heading: #1c4777;
  --link: #1c4777;
  --link-hover: #46a0ff;
  --border: rgba(28, 71, 119, 0.15);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    color-scheme: dark;
    --bg: #171b19;
    --surface: rgba(38, 43, 40, 0.9);
    --text: #e5e7eb;
    --muted: #a0aaa3;
    --heading: #b4d6ff;
    --link: #b4d6ff;
    --link-hover: #78baff;
    --border: rgba(255, 255, 255, 0.15);
  }
}

:root[data-theme="light"] {
  color-scheme: light;
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --bg: #171b19;
  --surface: rgba(38, 43, 40, 0.9);
  --text: #e5e7eb;
  --muted: #a0aaa3;
  --heading: #b4d6ff;
  --link: #b4d6ff;
  --link-hover: #78baff;
  --border: rgba(255, 255, 255, 0.15);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  min-height: 100%;
  background: var(--bg);
}

body {
  min-height: 100vh;
  width: 100%;
  overflow-x: hidden;
  font-family: "Trebuchet MS", "Lucida Sans Unicode",
    "Lucida Grande", "Lucida Sans", Arial, sans-serif;
  color: var(--text);
  background: var(--bg);
}

a {
  color: var(--link);
  text-decoration: none;
}

a:hover {
  color: var(--link-hover);
}

.post-footer,
.blog-feeds {
  display: none !important;
}

header {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
  padding: 20px;
  position: sticky;
  top: 0;
  z-index: 10;
  text-align: center;
  background: var(--surface);
  backdrop-filter: blur(15px) saturate(180%);
  -webkit-backdrop-filter: blur(15px) saturate(180%);
  border-bottom: 1px solid var(--border);
}

header h1 {
  font-size: 1.8rem;
  color: var(--heading);
}

#theme-toggle {
  padding: 8px 12px;
  border: 1px solid var(--border);
  border-radius: 8px;
  background: var(--surface);
  color: var(--text);
  font: inherit;
  cursor: pointer;
}

#theme-toggle:hover {
  border-color: var(--link-hover);
}

.container {
  width: 100%;
  margin: 0 auto;
  padding: 10px;
}

.blog-posts.hfeed {
  display: grid !important;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 400px), 1fr)) !important;
  gap: 20px !important;
  justify-content: center !important;
  padding: 0 !important;
  list-style: none !important;
  text-align: center !important;
}

.date-outer,
.date-posts {
  display: contents !important;
}

h2.date-header {
  display: none !important;
}

li.post-outer,
div.post-outer {
  aspect-ratio: 1 / 1 !important;
  display: grid !important;
  grid-template-rows: auto 1fr !important;
  gap: 8px;
  overflow: hidden !important;
  padding: 12px !important;
  border: 1px solid var(--border);
  border-radius: 15px !important;
  background: var(--surface) !important;
  backdrop-filter: blur(10px) saturate(180%);
  -webkit-backdrop-filter: blur(10px) saturate(180%);
}

li.post-outer img,
div.post-outer img {
  display: block;
  justify-self: center;
  width: 70%;
  height: auto;
  aspect-ratio: 1 / 1;
  object-fit: cover;
  border-radius: 10px;
  margin: 0 auto 8px;
}

li.post-outer h2.post-title a,
div.post-outer h2.post-title a {
  display: block;
  margin: 6px 0;
  color: var(--heading);
  font-size: 1.1rem;
  overflow-wrap: anywhere;
  text-align: center;
}

li.post-outer .post-body,
div.post-outer .post-body {
  min-height: 0;
  overflow: hidden;
}

li.post-outer .post-body p,
div.post-outer .post-body p {
  display: -webkit-box;
  overflow: hidden;
  -webkit-line-clamp: 3;
  -webkit-box-orient: vertical;
  color: var(--text);
  font-size: 0.85rem;
  text-align: justify;
}

.item-page div.post-outer {
  display: block !important;
  aspect-ratio: auto !important;
  max-width: 700px;
  margin: 20px auto;
  overflow: visible !important;
  text-align: left;
}

.item-page div.post-outer img {
  display: block;
  width: 100%;
  max-width: 500px;
  height: auto;
  aspect-ratio: auto;
  object-fit: contain;
  margin: 0 auto 15px;
}

.item-page div.post-body {
  overflow: visible;
}

.item-page div.post-body p {
  display: block;
  margin: 0 0 1em;
  overflow: visible;
  color: var(--text);
  line-height: 1.7;
  text-align: left;
}

.blog-pager {
  display: flex !important;
  justify-content: center !important;
  align-items: center !important;
  flex-wrap: wrap;
  gap: 10px !important;
  margin: 20px 0 !important;
}

.blog-pager a {
  display: inline-flex !important;
  align-items: center !important;
  justify-content: center !important;
  min-width: 90px;
  padding: 10px 16px;
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--surface);
  color: var(--link);
  font-size: 0.9rem;
  font-weight: 600;
  backdrop-filter: blur(10px);
}

.blog-pager a:hover {
  color: var(--link-hover);
}

.blog-pager .home-link {
  display: inline-flex !important;
}

footer {
  padding: 15px;
  border-top: 1px solid var(--border);
  color: var(--muted);
  font-size: 0.9rem;
  text-align: center;
}

@media (max-width: 480px) {
  .blog-posts.hfeed {
    grid-template-columns: 1fr !important;
  }

  header h1 {
    font-size: 1.4rem;
  }

  .blog-pager {
    gap: 6px !important;
  }

  .blog-pager a {
    min-width: 80px;
    padding: 9px 12px;
  }
}

head.script:
//
    (function () {
      try {
        var theme = localStorage.getItem("theme");
        if (theme === "light" || theme === "dark") {
          document.documentElement.setAttribute("data-theme", theme);
        }
      } catch (e) {}
    })();
//

body.script:
//
    (function () {
      var root = document.documentElement;
      var button = document.getElementById("theme-toggle");

      function getTheme() {
        return root.getAttribute("data-theme") || "system";
      }

      function updateButton() {
        button.textContent = "Theme: " +
          getTheme().charAt(0).toUpperCase() + getTheme().slice(1);
      }

      button.addEventListener("click", function () {
        var current = getTheme();
        var next = current === "system" ? "dark" :
          current === "dark" ? "light" : "system";

        if (next === "system") {
          root.removeAttribute("data-theme");
        } else {
          root.setAttribute("data-theme", next);
        }

        try {
          if (next === "system") {
            localStorage.removeItem("theme");
          } else {
            localStorage.setItem("theme", next);
          }
        } catch (e) {}

        updateButton();
      });

      updateButton();
    })();
//
